def _muon_python_step_param(
    p: Tensor,
    g: Tensor,
    state: dict[str, Tensor],
    *,
    lr: float,
    momentum: float,
    weight_decay: float,
    nesterov: bool,
    backend_steps: int,
) -> None:
    if weight_decay > 0.0:
        p.mul_(1.0 - lr * weight_decay)
    buf = state.get("momentum_buffer")
    if buf is None:
        buf = torch.zeros_like(g, dtype=torch.float32 if g.dtype != torch.float32 else g.dtype)
        state["momentum_buffer"] = buf
    buf.mul_(momentum).add_(g)
    effective_g = g.add(buf, alpha=momentum) if nesterov else buf
    update = zeropower_via_newtonschulz5(effective_g, steps=backend_steps)
    update *= max(1, update.size(0) / update.size(1)) ** 0.5
    p.add_(update.to(dtype=p.dtype), alpha=-lr)


def _muon_prefers_cuda_bucket(
    shape: tuple[int, int],
    *,
    bucket_size: int,
) -> bool:
    policy = MUON_CUDA_BUCKET_POLICY
    if policy in {"0", "false", "off", "none"}:
        return False
    if policy in {"1", "true", "on", "all", "force"}:
        return True
    rows, cols = int(shape[0]), int(shape[1])
    elements = rows * cols
    bucket_elements = elements * int(bucket_size)
    if bucket_size < 4:
        return False
    # Large square attention buckets now win on CUDA, but the small square
    # family still tends to lose to launch and gather overhead.
    if rows == cols:
        return bucket_size >= 8 or bucket_elements >= 1_000_000
    return rows < cols or elements >= 524288


def _muon_prefers_cuda_bucket_for_graph_capture(
    shape: tuple[int, int],
    *,
    bucket_size: int,
) -> bool:
    if _muon_prefers_cuda_bucket(shape, bucket_size=bucket_size):
        return True
    rows, cols = int(shape[0]), int(shape[1])
    elements = rows * cols
    bucket_elements = elements * int(bucket_size)
    if bucket_size < 2:
        return False
    # Full-step graph capture cannot tolerate Python Muon fallback in just one
    # optimizer bucket. The competition SSM blocks contribute several medium and
    # small matrix families (for example 64x64, 128x64, and the bf16 128x16
    # transition-source heads) that are still profitable to keep on the CUDA-side
    # grouped path once launch overhead is amortized across captured replay.
    if rows == cols:
        return bucket_size >= 4 and bucket_elements >= 16384
    if rows > cols:
        return bucket_elements >= 8192
    return bucket_elements >= 65536


def _muon_bucket_family_code(shape: tuple[int, int]) -> int:
    rows, cols = int(shape[0]), int(shape[1])
    if rows == cols:
        return 0
    if rows > cols:
        return 1
    if rows <= 384:
        return 2
    return 3


def _muon_family_workspace_dtype(shape: tuple[int, int], family_code: int, device: torch.device) -> torch.dtype:
    raw = os.environ.get("MUON_FAMILY_WORKSPACE_DTYPE", "auto").strip().lower()
    if raw in {"float", "float32", "fp32"}:
        return torch.float32
    if raw in {"bf16", "bfloat16"}:
        return torch.bfloat16
    if raw not in {"", "auto"}:
        raise ValueError(
            "MUON_FAMILY_WORKSPACE_DTYPE must be one of auto, float32, or bfloat16; "
            f"got {raw!r}"
        )
    if device.type == "cuda":
        props = torch.cuda.get_device_properties(device)
        if int(props.major) >= 9:
            return torch.bfloat16
    # Older local tuning boxes keep the more conservative fp32 workspace by
    # default. Hopper-class runs can opt into the bf16 workspace path via auto.
    return torch.float32


def _handle_muon_cuda_failure(stage: str, exc: Exception) -> None:
    mode = MUON_CUDA_ERROR_MODE if MUON_CUDA_ERROR_MODE in {"fallback", "warn", "raise"} else "warn"
    if mode == "raise":
        raise RuntimeError(f"Muon CUDA failure during {stage}") from exc
    if mode == "fallback":
        return
    message = (
        f"Muon CUDA failure during {stage}; falling back to Python Muon. "
        f"Set MUON_CUDA_ERROR_MODE=raise to hard-fail. Original error: {exc!r}"
    )
    if message in _MUON_CUDA_WARNED_FAILURE_KEYS:
        return
    _MUON_CUDA_WARNED_FAILURE_KEYS.add(message)
    warnings.warn(message, RuntimeWarning, stacklevel=2)


